        e = experiments[exp_id]
        print(f'{exp_id}: status={e.get(\"status\")}, conclusion={e.get(\"conclusion\")}, metrics={e.get(\"metrics\")}')
    else:
        print(f'{exp_id}: NOT FOUND')
print()
